CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,duration_minutes INTEGER NOT NULL,price INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS masters(id INTEGER PRIMARY KEY,name TEXT NOT NULL,specialty TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'client');
 CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS schedules(master_id INTEGER NOT NULL REFERENCES masters(id),weekday INTEGER NOT NULL,start_minute INTEGER NOT NULL,end_minute INTEGER NOT NULL,PRIMARY KEY(master_id,weekday));
 CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),service_id INTEGER NOT NULL REFERENCES services(id),master_id INTEGER NOT NULL REFERENCES masters(id),date TEXT NOT NULL,time TEXT NOT NULL,start_minute INTEGER NOT NULL,end_minute INTEGER NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','cancelled','completed')));
 CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),text TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0 CHECK(read IN (0,1)));
 CREATE TABLE IF NOT EXISTS blocks(id INTEGER PRIMARY KEY,master_id INTEGER NOT NULL REFERENCES masters(id),date TEXT NOT NULL,start_minute INTEGER NOT NULL,end_minute INTEGER NOT NULL,CHECK(start_minute<end_minute));
 CREATE UNIQUE INDEX IF NOT EXISTS booking_slot ON bookings(master_id,date,time) WHERE status!='cancelled';
 CREATE TRIGGER IF NOT EXISTS booking_overlap_insert BEFORE INSERT ON bookings WHEN NEW.status!='cancelled' BEGIN SELECT RAISE(ABORT,'booking_conflict') WHERE EXISTS(SELECT 1 FROM bookings b WHERE b.master_id=NEW.master_id AND b.date=NEW.date AND b.status!='cancelled' AND b.start_minute<NEW.end_minute AND b.end_minute>NEW.start_minute); END;
 CREATE TRIGGER IF NOT EXISTS booking_overlap_update BEFORE UPDATE ON bookings WHEN NEW.status!='cancelled' BEGIN SELECT RAISE(ABORT,'booking_conflict') WHERE EXISTS(SELECT 1 FROM bookings b WHERE b.id!=NEW.id AND b.master_id=NEW.master_id AND b.date=NEW.date AND b.status!='cancelled' AND b.start_minute<NEW.end_minute AND b.end_minute>NEW.start_minute); END;
